sys_script.script:
/**
 * 22-Car unavailability
 *
 * Blocks the reservation when the selected Car is not available.
 * Only evaluated when the Car is set or changed, so existing reservations can
 * still be closed or cancelled after a car is taken out of service.
 */
(function executeRule(/** @type {any} */ current, /** @type {any} */ previous) {
    if (!current.car.changes()) {
        return;
    }

    var carId = current.getValue('car');
    if (!carId) {
        return;
    }

    var car = new GlideRecord('x_2203703_car_re_0_car');
    if (!car.get(carId)) {
        return;
    }

    if (car.getValue('available') !== '1') {
        gs.addErrorMessage(
            'The car "' + car.getValue('name') + '" is currently unavailable and cannot be reserved.'
        );
        current.setAbortAction(true);
    }
})(current, previous);
